/** Shared menu/race music. No gameplay state or loading depends on audio succeeding. */
export type MusicPhase = 'silent' | 'menu' | 'race' | 'paused';
export interface MusicState {
  phase: MusicPhase;
  volume: number;
  muted: boolean;
  blocked: boolean;
  playing: boolean;
  settingsSaved: boolean;
}
export interface BackgroundMusicOptions {
  themeUrl?: string;
  preloadTheme?: boolean;
  raceUrl?: string;
  document?: Document;
  window?: Window;
  storage?: Pick<Storage, 'getItem' | 'setItem'> | null;
  createAudio?: (url: string) => HTMLAudioElement;
  createContext?: () => AudioContext;
  setTimeout?: typeof globalThis.setTimeout;
  clearTimeout?: typeof globalThis.clearTimeout;
}
export interface BackgroundMusic {
  setPhase(phase: MusicPhase, restartRace?: boolean): void;
  unlock(): void;
  preloadRace(): void;
  setRaceUrl?(url: string): void;
  setPresentationReady?(ready: boolean): void;
  silence(): void;
  setVolume(volume: number): void;
  setMuted(muted: boolean): void;
  getState(): MusicState;
  subscribe(listener: (state: MusicState) => void): () => void;
  fadeOut(durationMs?: number): Promise<void>;
  dispose(): void;
}
const SETTINGS_KEY = 'ai-friends-kart.music.v1';
const controllers = new WeakMap<Document, BackgroundMusic>();

export function createBackgroundMusic(options: BackgroundMusicOptions = {}): BackgroundMusic {
  const doc = options.document ?? globalThis.document;
  const win = options.window ?? globalThis.window;
  const existing = doc && controllers.get(doc);
  if (existing) return existing;
  const later = options.setTimeout ?? globalThis.setTimeout;
  const cancelTimer = options.clearTimeout ?? globalThis.clearTimeout;
  const safelyGetStorage = () => {
    try { return win?.localStorage; } catch { return null; }
  };
  const storage = options.storage === undefined ? safelyGetStorage() : options.storage;
  let volume = .65, muted = false;
  let settingsSaved = !!storage;
  try {
    const saved = JSON.parse(storage?.getItem(SETTINGS_KEY) ?? 'null');
    if (typeof saved?.volume === 'number' && Number.isFinite(saved.volume)) volume = Math.max(0, Math.min(1, saved.volume));
    if (typeof saved?.muted === 'boolean') muted = saved.muted;
  } catch { settingsSaved = false; /* Storage restrictions and corrupt preferences must never block play. */ }
  const persist = () => {
    try {
      if (!storage) { settingsSaved = false; return; }
      storage.setItem(SETTINGS_KEY, JSON.stringify({ volume, muted })); settingsSaved = true;
    } catch { settingsSaved = false; }
  };
  let currentRaceUrl=options.raceUrl ?? './assets/music/dfy_bgm.mp3';
  const audioFactory = options.createAudio ?? ((url: string) => new Audio(url));
  const tracks: HTMLAudioElement[] = [];
  try {
    tracks.push(audioFactory(options.themeUrl ?? './assets/music/dfy_theme.mp3'));
    tracks.push(audioFactory(currentRaceUrl));
  } catch {
    tracks.forEach(audio => { try { audio.pause(); audio.removeAttribute('src'); audio.load(); } catch { /* unavailable media backend */ } });
    // Audio is optional: even unavailable constructors must not stop loading/gameplay.
    let phase: MusicPhase = 'silent';
    const subscribers = new Set<(state: MusicState) => void>();
    const getState = (): MusicState => ({ phase, volume, muted, blocked: true, playing: false, settingsSaved });
    const emit = () => subscribers.forEach(listener => listener(getState()));
    const inert: BackgroundMusic = {
      getState, setPhase(next) { phase = next; emit(); }, unlock() {}, preloadRace() {}, silence() { phase = 'silent'; emit(); },
      setVolume(next) { if (Number.isFinite(next)) volume = Math.max(0, Math.min(1, next)); persist(); emit(); },
      setMuted(next) { muted = !!next; persist(); emit(); },
      subscribe(listener) { subscribers.add(listener); listener(getState()); return () => subscribers.delete(listener); },
      fadeOut() { phase = 'silent'; emit(); return Promise.resolve(); },
      dispose() { subscribers.clear(); if (doc) controllers.delete(doc); },
    };
    if (doc) controllers.set(doc, inert);
    return inert;
  }
  const [theme, race] = tracks;
  tracks.forEach(audio => { audio.loop = true; audio.preload = 'metadata'; audio.volume = 1; });
  // Menu pages may buffer the theme while their heavier UI graph loads.
  if (options.preloadTheme) { theme.preload = 'auto'; try { theme.load(); } catch { /* optional */ } }
  // A cold document always starts new media at zero. Same-document scene hops
  // keep these elements alive, so they preserve position without storage.
  let context: AudioContext | undefined;
  let graphFailed = false, racePreloaded = false;
  let gains: GainNode[] = [];
  let sources: MediaElementAudioSourceNode[] = [];
  let presentationReady=true;
  let phase: MusicPhase = 'silent', blocked = false, playing = false, disposed = false;
  let hidden = !!doc?.hidden, fading = false, generation = 0;
  let fadeTimer: ReturnType<typeof setTimeout> | undefined;
  let finishFade: (() => void) | undefined;
  let phaseTimer: ReturnType<typeof setTimeout> | undefined;
  let transitionVersion = 0;
  let outgoing: HTMLAudioElement | undefined;
  const listeners = new Set<(state: MusicState) => void>();
  const getState = (): MusicState => ({ phase, volume, muted, blocked, playing, settingsSaved });
  const emit = () => listeners.forEach(listener => listener(getState()));
  const target = () => phase === 'menu' ? theme : phase === 'race' || phase === 'paused' ? race : undefined;
  const desired = (audio: HTMLAudioElement) => !disposed && !hidden && presentationReady && !muted && volume > 0 && target() === audio;
  const mayPlay = (audio: HTMLAudioElement) => desired(audio) || (!disposed && !hidden && presentationReady && !muted && volume > 0 && (audio === outgoing || fading));
  const level = () => !presentationReady || hidden || muted || phase === 'silent' ? 0 : volume * (phase === 'paused' ? .3 : 1);
  const applyGains = () => gains.forEach((gain, index) => {
    gain.gain.cancelScheduledValues(context!.currentTime);
    gain.gain.setValueAtTime(desired(tracks[index]) ? level() : 0, context!.currentTime);
  });
  const ensureGraph = () => {
    if (context) return true;
    if (graphFailed) return false;
    try {
      const factory = options.createContext ?? (() => {
        const audioWindow = win as Window & { AudioContext?: typeof AudioContext; webkitAudioContext?: typeof AudioContext };
        const Constructor = audioWindow?.AudioContext ?? audioWindow?.webkitAudioContext;
        if (!Constructor) throw new Error('Web Audio unavailable');
        return new Constructor();
      });
      context = factory();
      tracks.forEach(audio => sources.push(context!.createMediaElementSource(audio)));
      tracks.forEach(() => gains.push(context!.createGain()));
      sources.forEach((source, index) => { source.connect(gains[index]); gains[index].connect(context!.destination); });
      applyGains();
      return true;
    } catch {
      // Fail silent instead of relying on HTMLMediaElement.volume, which iOS ignores.
      blocked = true;
      // A source attached to a media element cannot be created twice, even after
      // disconnect. Treat partial graph construction failure as terminal for it.
      if (context) graphFailed = true;
      tracks.forEach(audio => audio.pause());
      sources.forEach(source => source.disconnect());
      gains.forEach(gain => gain.disconnect());
      if (context) void context.close().catch(() => {});
      context = undefined; sources = []; gains = [];
      return false;
    }
  };
  const cancelFade = () => {
    if (fadeTimer !== undefined) cancelTimer(fadeTimer);
    fadeTimer = undefined;
    fading = false;
    const resolve = finishFade; finishFade = undefined; resolve?.();
  };
  const cancelTransition = (pauseOutgoing = true) => {
    transitionVersion++;
    if (phaseTimer !== undefined) cancelTimer(phaseTimer);
    phaseTimer = undefined;
    if (pauseOutgoing && outgoing && outgoing !== target()) outgoing.pause();
    outgoing = undefined;
  };
  const attempt = (preserveRamp = false) => {
    if (disposed || fading) return;
    const selected = target();
    tracks.forEach(audio => { if (!mayPlay(audio)) audio.pause(); });
    playing = false;
    if (!selected || !desired(selected)) { if (!preserveRamp) applyGains(); emit(); return; }
    if (!ensureGraph()) { emit(); return; }
    if (!preserveRamp) {
      applyGains();
      if (selected.paused || context!.state !== 'running' || blocked) {
        // Wall-clock transitions can finish while autoplay keeps the audio clock
        // suspended. Start a new fade when playback is actually retried/restored.
        const gain = gains[tracks.indexOf(selected)].gain;
        const now = context!.currentTime;
        gain.cancelScheduledValues(now);
        gain.setValueAtTime(0, now);
        gain.linearRampToValueAtTime(level(), now + .5);
        const version = ++transitionVersion;
        phaseTimer = later(() => {
          if (disposed || version !== transitionVersion) return;
          phaseTimer = undefined; applyGains();
        }, 500);
      }
    }
    if (!selected.paused && context!.state === 'running' && !blocked) {
      playing = true; emit(); return;
    }
    const token = ++generation;
    // Both calls happen in this stack, preserving transient user activation on iOS.
    let resumed: Promise<void>;
    try { resumed = context!.state === 'running' ? Promise.resolve() : context!.resume(); }
    catch { resumed = Promise.reject(new Error('Audio resume failed')); }
    let started: Promise<void>;
    try {
      // A failed resource needs a fresh load before the next user-triggered retry.
      if (selected.error) {
        const position = selected.currentTime;
        selected.load();
        try { selected.currentTime = position; } catch { /* seek when media is available */ }
      }
      started = Promise.resolve(selected.play());
    }
    catch { started = Promise.reject(new Error('Audio play failed')); }
    void started.then(() => { if (!mayPlay(selected)) selected.pause(); }, () => {});
    void Promise.all([resumed, started]).then(() => {
      if (!mayPlay(selected)) selected.pause();
      if (disposed || token !== generation) return;
      blocked = false; playing = desired(selected) && !selected.paused; emit();
    }).catch(() => {
      if (!mayPlay(selected)) selected.pause();
      if (disposed || token !== generation) return;
      blocked = true; playing = false; emit();
    });
  };

  const refresh = () => { generation++; cancelFade(); cancelTransition(); attempt(); };
  const unlock = () => {
    if (disposed || hidden) return;
    // An early loading-screen gesture may unlock the context without playing a track.
    if (!context && !ensureGraph()) { emit(); return; }
    if ((!target() || !presentationReady) && context!.state !== 'running') {
      try { void context!.resume().catch(() => { if (!disposed) { blocked = true; emit(); } }); } catch { blocked = true; emit(); }
    }
    // Ordinary input must not cancel the phase crossfade or restart playback.
    attempt(phaseTimer !== undefined);
  };
  const onMediaError = (event: Event) => {
    if (disposed || event.target !== target()) return;
    blocked = true; playing = false; emit();
  };
  tracks.forEach(audio => audio.addEventListener('error', onMediaError));
  const onVisibility = () => { hidden = !!doc.hidden; refresh(); };
  const onPageHide = () => { hidden = true; refresh(); };
  const onPageShow = () => { hidden = !!doc?.hidden; refresh(); };
  const controller: BackgroundMusic = {
    getState,
    subscribe(listener) { if (disposed) return () => {}; listeners.add(listener); listener(getState()); return () => listeners.delete(listener); },
    setPhase(next, restartRace = false) {
      if (disposed) return;
      if (phase === next && !restartRace && !fading) { attempt(phaseTimer !== undefined); return; }
      const previous = target();
      if (next === 'race' && (restartRace || (phase !== 'race' && phase !== 'paused'))) {
        try { race.currentTime = 0; } catch { /* not loaded */ }
      }
      generation++; cancelFade(); cancelTransition();
      phase = next;
      if (hidden || muted || volume <= 0 || !ensureGraph()) { attempt(); return; }
      const selected = target();
      outgoing = previous !== selected && previous && !previous.paused ? previous : undefined;
      const seconds = previous === selected ? .2 : .5;
      gains.forEach((gain, index) => {
        const now = context!.currentTime;
        const current = tracks[index];
        const from = current === selected && current.paused ? 0 : gain.gain.value;
        gain.gain.cancelScheduledValues(now);
        gain.gain.setValueAtTime(from, now);
        gain.gain.linearRampToValueAtTime(current === selected ? level() : 0, now + seconds);
      });
      const version = ++transitionVersion;
      phaseTimer = later(() => {
        if (disposed || version !== transitionVersion) return;
        phaseTimer = undefined;
        if (outgoing && outgoing !== target()) outgoing.pause();
        outgoing = undefined;
        applyGains();
      }, seconds * 1000);
      attempt(true);
    },
    unlock,
    silence() {
      if (disposed) return;
      phase = 'silent';
      // Loading/countdowns must be silent immediately, unlike navigational fades.
      generation++; cancelFade(); cancelTransition();
      tracks.forEach(audio => audio.pause());
      playing = false; applyGains(); emit();
    },
    setPresentationReady(ready) {if(disposed||presentationReady===ready)return;presentationReady=ready;refresh();},
    setRaceUrl(url) {
      if(disposed||currentRaceUrl===url)return;
      currentRaceUrl=url;
      generation++;race.pause();race.src=url;race.preload='metadata';racePreloaded=false;
      try {race.load();}catch{/* Optional music never blocks a scene. */}
    },
    preloadRace() {
      if (disposed || racePreloaded) return;
      racePreloaded = true;
      try { race.preload = 'auto'; race.load(); } catch { /* Playback can still retry later. */ }
    },
    setVolume(next) { if (disposed || !Number.isFinite(next)) return; volume = Math.max(0, Math.min(1, next)); persist(); refresh(); },
    setMuted(next) { if (disposed) return; muted = !!next; persist(); refresh(); },
    fadeOut(durationMs = 500) {
      if (disposed) return Promise.resolve();
      cancelFade();
      cancelTransition(false);
      generation++;
      const token = generation;
      fading = true;
      const ms = Number.isFinite(durationMs) ? Math.max(0, Math.min(500, durationMs)) : 500;
      gains.forEach(gain => {
        const now = context!.currentTime;
        gain.gain.cancelScheduledValues(now);
        gain.gain.setValueAtTime(gain.gain.value, now);
        gain.gain.linearRampToValueAtTime(0, now + ms / 1000);
      });
      return new Promise<void>(resolve => {
        finishFade = resolve;
        fadeTimer = later(() => {
          fadeTimer = undefined; finishFade = undefined;
          if (!disposed && token === generation) {
            tracks.forEach(audio => audio.pause());
            phase = 'silent'; fading = false; playing = false; applyGains(); emit();
          }
          resolve();
        }, ms);
      });
    },
    dispose() {
      if (disposed) return;
      disposed = true; generation++; cancelFade(); cancelTransition();
      tracks.forEach(audio => { audio.removeEventListener('error', onMediaError); audio.pause(); audio.removeAttribute('src'); audio.load(); });
      doc?.removeEventListener('visibilitychange', onVisibility);
      doc?.removeEventListener('pointerdown', unlock, true);
      doc?.removeEventListener('pointerup', unlock, true);
      doc?.removeEventListener('touchend', unlock, true);
      doc?.removeEventListener('keydown', unlock, true);
      win?.removeEventListener('pagehide', onPageHide);
      win?.removeEventListener('pageshow', onPageShow);
      sources.forEach(source => source.disconnect()); gains.forEach(gain => gain.disconnect());
      if (context) void context.close().catch(() => {});
      listeners.clear(); if (doc) controllers.delete(doc);
    },
  };
  doc?.addEventListener('visibilitychange', onVisibility);
  doc?.addEventListener('pointerdown', unlock, true);
  doc?.addEventListener('pointerup', unlock, true);
  doc?.addEventListener('touchend', unlock, true);
  doc?.addEventListener('keydown', unlock, true);
  win?.addEventListener('pagehide', onPageHide);
  win?.addEventListener('pageshow', onPageShow);
  if (doc) controllers.set(doc, controller);
  return controller;
}

src/character-identity.js.content:
/** Display-only identity from the supplied character sheets. Machine IDs stay stable. */
export const CHARACTER_IDENTITIES = Object.freeze({
  whale: Object.freeze({label:'大肥鱼', emblem:'./character-emblems/whale.png'}),
  gemini: Object.freeze({label:'双子', emblem:'./character-emblems/gemini.png'}),
  gpt: Object.freeze({label:'小吉', emblem:'./character-emblems/gpt.png'}),
  claude: Object.freeze({label:'克洛德', emblem:'./character-emblems/claude.png'}),
  grok: Object.freeze({label:'洛可', emblem:'./character-emblems/grok.png'}),
  glm: Object.freeze({label:'智谱', emblem:'./character-emblems/glm.png'}),
});
export function characterIdentity(id) {
  return typeof id === 'string' && Object.hasOwn(CHARACTER_IDENTITIES,id) ? CHARACTER_IDENTITIES[id] : null;
}
export function characterDisplayName(id, fallback = '未知选手') {
  return characterIdentity(id)?.label ?? fallback;
}
/** Decorative beside the name; meaningful alt text when the emblem stands alone. */
export function characterEmblem(id, decorative = true) {
  const identity = characterIdentity(id);
  return identity ? `<img class="character-emblem" src="${identity.emblem}" width="128" height="128" alt="${decorative ? '' : `${identity.label}纹章`}"${decorative ? ' aria-hidden="true"' : ''} decoding="async" draggable="false">` : '';
}

src/character-profiles.ts.content:
import {resolveMap,type MapId} from './map-profiles';
import {characterIdentity} from './character-identity.js';
/** One authoritative, balanced roster shared by menu, player and opponents. */
export type CharacterId = 'whale'|'gemini'|'gpt'|'claude'|'grok'|'glm';
export type CharacterProfile = {id:CharacterId;label:string;nickname:string;description:string;color:string;emblem:string;acceleration:number;topSpeed:number;steering:number};
export const CHARACTER_PROFILES:readonly Readonly<CharacterProfile>[] = Object.freeze([
 {id:'whale',nickname:'轻快巡游',description:'起步轻快，转向灵活；直线极速稍低。',color:'#77dcea',acceleration:1.06,topSpeed:.92,steering:1.02},
 {id:'gemini',nickname:'弯道双星',description:'最灵活的弯道选择，起步需要一点耐心。',color:'#a5a4ff',acceleration:.92,topSpeed:1,steering:1.08},
 {id:'gpt',nickname:'全能伙伴',description:'三项均衡，适合熟悉不同赛道。',color:'#f4e4c8',acceleration:1,topSpeed:1,steering:1},
 {id:'claude',nickname:'起跑专家',description:'加速最强，较温和的极速让节奏更从容。',color:'#eeac8e',acceleration:1.08,topSpeed:.96,steering:.96},
 {id:'grok',nickname:'直线先锋',description:'极速最高；请提前为转弯和起步留余量。',color:'#b89bdb',acceleration:.96,topSpeed:1.08,steering:.96},
 {id:'glm',nickname:'疾风领航',description:'兼顾极速与转向，起步略慢。',color:'#9cddad',acceleration:.94,topSpeed:1.04,steering:1.02},
].map(profile=>Object.freeze({...profile,...characterIdentity(profile.id)} as CharacterProfile)));
export function resolveCharacter(id:unknown):Readonly<CharacterProfile>{return CHARACTER_PROFILES.find(profile=>profile.id===id)||CHARACTER_PROFILES[0];}
export const MAP_BASELINES=Object.freeze({coast:Object.freeze({maxSpeed:42,acceleration:18,steering:7}),waterpark:Object.freeze({maxSpeed:22,acceleration:8.6,steering:11})});
export function characterTuning(id:unknown,mapId:MapId){
 const profile=resolveCharacter(id),base=MAP_BASELINES[resolveMap(mapId).vehicle==='kart'?'coast':'waterpark'];
 return {maxSpeed:base.maxSpeed*profile.topSpeed,acceleration:base.acceleration*profile.acceleration,steering:base.steering*profile.steering,multipliers:{topSpeed:profile.topSpeed,acceleration:profile.acceleration,steering:profile.steering}};
}

src/closed-circuit.ts.content:
import { Vec3 } from 'playcanvas';

export type CircuitPoint = Readonly<{x: number; y: number; z: number}> | readonly [number, number, number];
export type CircuitOptions = {arcSteps?: number; legacySeamTangent?: boolean};
type CubicAxis = readonly [number, number, number, number];
type CubicSegment = {x: CubicAxis; y: CubicAxis; z: CubicAxis};

/** Map-neutral, closed centripetal Catmull–Rom curve with a metre-distance table.
 * Geometry is built once; every scene, racer and camera consumes this sampler.
 * The legacy seam option exists solely to verify the historical migration route. */
export class ClosedCircuit {
  readonly points: readonly Vec3[];
  readonly arcs: number[] = [0];
  readonly length: number;
  readonly arcSteps: number;
  private readonly legacySeamTangent: boolean;
  private readonly segments: readonly CubicSegment[];
  constructor(points: readonly CircuitPoint[], options: CircuitOptions = {}) {
    if (points.length < 4) throw new Error('A closed circuit needs at least four points');
    this.points = points.map(point => Array.isArray(point) ? new Vec3(point[0], point[1], point[2]) : new Vec3((point as Vec3).x, (point as Vec3).y, (point as Vec3).z));
    if (this.points.some(point => ![point.x, point.y, point.z].every(Number.isFinite))) throw new Error('Circuit points must be finite');
    // Coefficients are static. Avoid rebuilding tangent weights and temporary
    // vectors for every rider/camera/wake sample on mobile devices.
    this.segments = this.points.map((_, segment) => {
      const n = this.points.length, [p0, p1, p2, p3] = [-1, 0, 1, 2].map(i => this.points[(segment + i + n) % n]);
      let d0 = Math.sqrt(p0.clone().sub(p1).length()), d1 = Math.sqrt(p1.clone().sub(p2).length()), d2 = Math.sqrt(p2.clone().sub(p3).length());
      if (d1 < 1e-4) d1 = 1;
      if (d0 < 1e-4) d0 = d1;
      if (d2 < 1e-4) d2 = d1;
      const axis = (a: number, b: number, c: number, d: number): CubicAxis => {
        const m1 = ((b - a) / d0 - (c - a) / (d0 + d1) + (c - b) / d1) * d1;
        const m2 = ((c - b) / d1 - (d - b) / (d1 + d2) + (d - c) / d2) * d1;
        return [b, m1, -3 * b + 3 * c - 2 * m1 - m2, 2 * b - 2 * c + m1 + m2];
      };
      return {x: axis(p0.x, p1.x, p2.x, p3.x), y: axis(p0.y, p1.y, p2.y, p3.y), z: axis(p0.z, p1.z, p2.z, p3.z)};
    });
    // Include every control knot in the distance table. Centripetal segments
    // share tangent directions but not parameter speed; straddling a knot in a
    // table interval would otherwise create a small visible speed pulse.
    this.arcSteps = Number.isFinite(options.arcSteps) ? Math.max(64, Math.floor(options.arcSteps!)) : Math.ceil(1800 / points.length) * points.length;
    this.legacySeamTangent = options.legacySeamTangent === true;
    let previous = this.point(0), total = 0;
    for (let i = 1; i <= this.arcSteps; i++) {
      const next = this.point(i / this.arcSteps);
      total += next.clone().sub(previous).length(); this.arcs.push(total); previous = next;
    }
    if (total < 1e-6) throw new Error('Circuit length must be positive');
    this.length = total;
  }
  point(parameter: number): Vec3 {
    const n = this.points.length;
    const p = (((Number.isFinite(parameter) ? parameter : 0) % 1) + 1) % 1 * n;
    const index = Math.floor(p), t = p - index, segment = this.segments[index];
    const component = ([a, b, c, d]: CubicAxis) => a + b * t + c * t * t + d * t * t * t;
    return new Vec3(component(segment.x), component(segment.y), component(segment.z));
  }
  parameterAt(u: number): number {
    const target = Math.max(0, Math.min(1, Number.isFinite(u) ? u : 0)) * this.length;
    let low = 0, high = this.arcs.length - 1;
    while (low <= high) {
      const mid = Math.floor((low + high) / 2);
      if (this.arcs[mid] < target) low = mid + 1;
      else if (this.arcs[mid] > target) high = mid - 1;
      else return mid / this.arcSteps;
    }
    const index = Math.max(0, Math.min(this.arcSteps - 1, high));
    const span = this.arcs[index + 1] - this.arcs[index];
    return (index + (span > 0 ? (target - this.arcs[index]) / span : 0)) / this.arcSteps;
  }
  sample(distance: number, lateral = 0) {
    const u = (((Number.isFinite(distance) ? distance : 0) / this.length) % 1 + 1) % 1;
    const parameter = this.parameterAt(u), p = this.point(parameter);
    const before = this.legacySeamTangent ? Math.max(0, parameter - .0001) : parameter - .0001;
    const after = this.legacySeamTangent ? Math.min(1, parameter + .0001) : parameter + .0001;
    const t = this.point(after).sub(this.point(before)).normalize();
    const n = new Vec3(t.z, 0, -t.x).normalize();
    p.add(n.clone().mulScalar(Number.isFinite(lateral) ? lateral : 0));
    return {p, t, n, u, angle: Math.atan2(t.x, t.z)};
  }
  /** Signed yaw change per metre; positive bends toward the positive lane side. */
  curvature(distance: number, lookAhead = 7): number {
    const span = Number.isFinite(lookAhead) && lookAhead > 0 ? lookAhead : 7;
    const a = this.sample(distance).t, b = this.sample(distance + span).t;
    return Math.atan2(a.z * b.x - a.x * b.z, a.x * b.x + a.z * b.z) / span;
  }
}

src/coast-race-feedback.ts.content:
import { pulseTarget, type Combatant,type RouteInteractions } from './npc-tactics';
import type { RaceHudSnapshot } from './race-shell';

/** Match the existing coast release rule exactly; water has its own tuning. */
export const COAST_DRIFT = Object.freeze({ readyAfter: .6, maxCharge: 1.6 });
export const coastDriftReady = (charge: number) => charge > COAST_DRIFT.readyAfter;
export const coastDriftBoost = (charge: number) => coastDriftReady(charge) ? Math.min(2.5, charge * 1.5) : 0;

type Tangent = {x: number; z: number};
type TrackSample = (distance: number) => {t: Tangent};
const clamp = (value: number, low: number, high: number) => Math.max(low, Math.min(high, value));
const turnAngle = (a: Tangent, b: Tangent) => Math.abs(Math.atan2(a.x * b.z - a.z * b.x, a.x * b.x + a.z * b.z));

/** Coast rivals lift before stronger bends and recover on exits. Two overlapping
 * 22m windows avoid cancelling the opposite turns of the downhill chicane.
 * Only track geometry and the rival's speed are read: no player/rank catch-up.
 * driveSpeed still owns acceleration/braking; this never sets speed directly. */
export function coastCornerPace(distance: number, speed: number, sample: TrackSample) {
  const approach = clamp(Math.max(0, speed) * .3, 0, 16);
  const a = sample(distance).t, b = sample(distance + 22).t;
  const c = sample(distance + approach).t, d = sample(distance + approach + 22).t;
  const angle = Math.max(turnAngle(a, b), turnAngle(c, d));
  const t = clamp((angle - .18) / .47, 0, 1);
  return 1 - .14 * t * t * (3 - 2 * t);
}

export function coastHudFeedback(actor: Combatant, racers: readonly Combatant[], length: number,
  charge: number, label: (id: string) => string,routes?:RouteInteractions): Pick<RaceHudSnapshot, 'chargeMax' | 'chargeLabel' | 'chargeState' | 'itemHelp'> {
  const ready = coastDriftReady(charge), full = charge >= COAST_DRIFT.maxCharge;
  const chargeState = full ? 'full' : ready ? 'ready' : charge > 0 ? 'charging' : 'idle';
  const effects = [actor.boost > 0 ? `加速 ${actor.boost.toFixed(1)} 秒` : '', actor.shield > 0 ? `护盾 ${actor.shield.toFixed(1)} 秒` : '', actor.slow > 0 ? `减速 ${actor.slow.toFixed(1)} 秒` : ''].filter(Boolean).join(' · ');
  const drift = ready ? `${full ? '蓄力已满' : '漂移就绪'} · 松开 Shift 加速 ${coastDriftBoost(charge).toFixed(1)} 秒` : charge > 0 ? '漂移蓄力中 · 继续保持转向' : Math.abs(actor.speed) < .1 ? '按住 W 油门起步' : '左 Shift + A / D 手刹漂移';
  let itemHelp: string | undefined;
  if (actor.held === 'pulse') {
    const target = pulseTarget(actor, racers, length,routes);
    itemHelp = target ? `${label(target.id)}${target.shield > 0 ? ' 有护盾 · 脉冲会被挡住' : ' · E 发射脉冲'}` : '前方无目标 · E 转为 1.9 秒加速';
  } else if (actor.held === 'boost') itemHelp = 'E 加速 3.3 秒 · 适合出弯直线';
  else if (actor.held === 'shield') itemHelp = 'E 护盾 6 秒 · 抵挡碰撞与脉冲';
  return {chargeMax: COAST_DRIFT.maxCharge, chargeLabel: charge > 0 ? drift : effects || drift, chargeState, itemHelp};
}

src/control-mode.ts.content:
/** Shared input preference and primary-device classification; never UA/width based. */
export type ControlMode = 'auto' | 'touch' | 'desktop';
export type EffectiveControlMode = Exclude<ControlMode, 'auto'>;
export type ControlCapabilities = {touchPoints: number; coarse: boolean; fine: boolean; hover: boolean; anyCoarse: boolean; pointerMedia: boolean};
export const CONTROL_PREFERENCE_EVENT = 'racecontrolpreferencechange';
export const CONTROL_MODE_OPTIONS = '<option value="auto">自动识别</option><option value="touch">触屏按键</option><option value="desktop">键盘鼠标</option>';
const KEY = 'kart-control-mode';
const preferences = new WeakMap<Document, ControlMode>();
export const normalizeControlMode = (value: unknown): ControlMode => value === 'touch' || value === 'desktop' ? value : 'auto';
export function readControlPreference(win?: Window | null): ControlMode {
  try { return normalizeControlMode((win ?? globalThis.window)?.localStorage?.getItem(KEY)); } catch { return 'auto'; }
}
export function controlPreference(doc: Document) { return preferences.get(doc) ?? readControlPreference(doc.defaultView); }
export function setControlPreference(doc: Document, mode: ControlMode) {
  const preference = normalizeControlMode(mode); let saved = false;
  preferences.set(doc, preference);
  try { const storage = (doc.defaultView ?? globalThis.window)?.localStorage; if (storage) { storage.setItem(KEY, preference); saved = true; } } catch { /* Session preference remains usable. */ }
  doc.dispatchEvent?.(new CustomEvent(CONTROL_PREFERENCE_EVENT, {detail: {preference, saved}}));
  return saved;
}
export function bindControlPreferenceSelect(doc: Document, selector: HTMLSelectElement) {
  const sync = () => { selector.value = controlPreference(doc); };
  const change = () => setControlPreference(doc, normalizeControlMode(selector.value));
  sync(); selector.addEventListener('change', change); doc.addEventListener?.(CONTROL_PREFERENCE_EVENT, sync);
  return () => { selector.removeEventListener('change', change); doc.removeEventListener?.(CONTROL_PREFERENCE_EVENT, sync); };
}
export function resolveControlMode(preference: ControlMode, input: ControlCapabilities, observed: EffectiveControlMode | null = null): EffectiveControlMode {
  if (preference !== 'auto') return preference;
  if (observed) return observed;
  // A primary mouse/trackpad wins over a secondary touchscreen on hybrid PCs.
  if (input.fine && input.hover) return 'desktop';
  if (input.touchPoints > 0 && (input.coarse || (input.anyCoarse && !input.hover) || !input.pointerMedia)) return 'touch';
  return 'desktop';
}

src/item-models.ts.content:
import * as pc from 'playcanvas';

/** Original procedural geometry, authored for AI Friends Kart. AGPL-3.0-only.
 * These are the source models, not borrowed game assets or font characters.
 * The inventory portraits and world entities consume these same triangles.
 */
export type ItemKind = 'boost' | 'shield' | 'pulse';
export type ItemDisplay = ItemKind | 'mystery';
type Point = readonly [number, number, number];
type Point2 = readonly [number, number];
export interface ItemModelPart {
  readonly color: string;
  readonly metalness: number;
  readonly positions: readonly number[];
  readonly normals: readonly number[];
  readonly indices: readonly number[];
}
export interface ItemGeometry {
  readonly type: ItemDisplay;
  readonly parts: readonly ItemModelPart[];
  readonly bounds: { readonly min: Point; readonly max: Point };
  readonly triangleCount: number;
}
export const ITEM_MODEL_METADATA = Object.freeze({
  author: 'AI Friends Kart contributors',
  license: 'AGPL-3.0-only',
  source: 'src/item-models.ts',
  original: true,
  portrait: 'Orthographic, lit triangle projection of the world geometry',
  items: Object.freeze({
    boost: Object.freeze({ name: 'Comet boost', color: '#ff9d34', description: 'Finned orange rocket with an ivory speed crest and a faceted flame' }),
    shield: Object.freeze({ name: 'Tide shield', color: '#55d9f2', description: 'Deep-blue kite shield with a silver-cyan bevel and a raised crest' }),
    pulse: Object.freeze({ name: 'Nova pulse', color: '#ed70e9', description: 'Faceted plasma core enclosed by crossed luminous orbital rings' }),
    mystery: Object.freeze({ name: 'Mystery item', color: '#ffdb6b', description: 'Solid, beveled gold question mark with a separate raised dot' }),
  }),
});

const sub = (a: Point, b: Point): Point => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const cross = (a: Point, b: Point): Point => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const dot = (a: Point, b: Point) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const unit = (v: Point): Point => { const n = Math.hypot(...v); return [v[0] / n, v[1] / n, v[2] / n]; };
const rotate = (p: Point, x = 0, y = 0, z = 0): Point => {
  const a = x * Math.PI / 180, b = y * Math.PI / 180, c = z * Math.PI / 180;
  const q: Point = [p[0], p[1] * Math.cos(a) - p[2] * Math.sin(a), p[1] * Math.sin(a) + p[2] * Math.cos(a)];
  const r: Point = [q[0] * Math.cos(b) + q[2] * Math.sin(b), q[1], -q[0] * Math.sin(b) + q[2] * Math.cos(b)];
  return [r[0] * Math.cos(c) - r[1] * Math.sin(c), r[0] * Math.sin(c) + r[1] * Math.cos(c), r[2]];
};
type MutablePart = { color: string; metalness: number; positions: number[]; normals: number[]; indices: number[] };

/** Flat normals intentionally preserve toy-like facets and hard metal bevels. */
class ModelBuilder {
  parts = new Map<string, MutablePart>();
  triangle(color: string, a: Point, b: Point, c: Point, metalness = .2) {
    const normal = cross(sub(b, a), sub(c, a));
    if (Math.hypot(...normal) < 1e-9) return;
    const key = `${color}:${metalness}`;
    if (!this.parts.has(key)) this.parts.set(key, { color, metalness, positions: [], normals: [], indices: [] });
    const part = this.parts.get(key)!, offset = part.positions.length / 3, n = unit(normal);
    part.positions.push(...a, ...b, ...c); part.normals.push(...n, ...n, ...n); part.indices.push(offset, offset + 1, offset + 2);
  }
  quad(color: string, a: Point, b: Point, c: Point, d: Point, metalness = .2) {
    this.triangle(color, a, b, c, metalness); this.triangle(color, a, c, d, metalness);
  }
  /** Closed ring profile around +Y. End points may have zero radius. */
  lathe(profile: readonly (readonly [number, number])[], colors: readonly string[], segments = 12, center: Point = [0, 0, 0]) {
    const at = (ring: number, segment: number): Point => {
      const [y, r] = profile[ring], a = segment * Math.PI * 2 / segments;
      return [center[0] + Math.cos(a) * r, center[1] + y, center[2] + Math.sin(a) * r];
    };
    for (let i = 0; i < profile.length - 1; i++) for (let j = 0; j < segments; j++) {
      this.quad(colors[Math.min(i, colors.length - 1)], at(i, j), at(i + 1, j), at(i + 1, j + 1), at(i, j + 1));
    }
  }
  /** Ear-clipped 2D extrusion; front is +Z. Also supports concave symbols. */
  extrude(points: readonly Point2[], front: number, back: number, face: string, edge: string) {
    const p = [...points];
    const area = p.reduce((s, v, i) => { const q = p[(i + 1) % p.length]; return s + v[0] * q[1] - q[0] * v[1]; }, 0);
    if (area < 0) p.reverse();
    const at = (i: number, z: number): Point => [p[i][0], p[i][1], z];
    const indices = p.map((_, i) => i);
    const side = (a: Point2, b: Point2, c: Point2) => (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);
    while (indices.length > 2) {
      let clipped = false;
      for (let i = 0; i < indices.length; i++) {
        const a = indices[(i + indices.length - 1) % indices.length], b = indices[i], c = indices[(i + 1) % indices.length];
        if (side(p[a], p[b], p[c]) <= 1e-10) continue;
        if (indices.some(j => j !== a && j !== b && j !== c && side(p[a], p[b], p[j]) >= -1e-10 && side(p[b], p[c], p[j]) >= -1e-10 && side(p[c], p[a], p[j]) >= -1e-10)) continue;
        this.triangle(face, at(a, front), at(b, front), at(c, front));
        this.triangle(edge, at(c, back), at(b, back), at(a, back));
        indices.splice(i, 1); clipped = true; break;
      }
      if (!clipped) throw new Error('Item silhouette cannot be triangulated');
    }
    for (let i = 0; i < p.length; i++) {
      const j = (i + 1) % p.length;
      this.quad(edge, at(i, back), at(j, back), at(j, front), at(i, front));
    }
  }
  /** Faceted domed face over a convex silhouette, with a visible raised rim. */
  plate(points: readonly Point2[], z: number, edge: string, face: string, centerZ: number) {
    for (let i = 0; i < points.length; i++) {
      const p = points[i], q = points[(i + 1) % points.length];
      this.quad(edge, [p[0], p[1], z], [q[0], q[1], z], [q[0] * .82, q[1] * .82, z + .055], [p[0] * .82, p[1] * .82, z + .055], .45);
      this.triangle(face, [p[0] * .82, p[1] * .82, z + .055], [q[0] * .82, q[1] * .82, z + .055], [0, 0, centerZ]);
    }
  }
  torus(radius: number, thickness: number, color: string, rotation: Point, segments = 28, sides = 6) {
    const at = (u: number, v: number): Point => {
      const a = u * 2 * Math.PI / segments, b = v * 2 * Math.PI / sides;
      return rotate([(radius + thickness * Math.cos(b)) * Math.cos(a), (radius + thickness * Math.cos(b)) * Math.sin(a), thickness * Math.sin(b)], ...rotation);
    };
    for (let i = 0; i < segments; i++) for (let j = 0; j < sides; j++) this.quad(color, at(i, j), at(i + 1, j), at(i + 1, j + 1), at(i, j + 1), .35);
  }
  finish(type: ItemDisplay, rotation: Point = [0, 0, 0]): ItemGeometry {
    const parts = [...this.parts.values()];
    const min = [Infinity, Infinity, Infinity], max = [-Infinity, -Infinity, -Infinity];
    for (const part of parts) for (let i = 0; i < part.positions.length; i += 3) {
      const p = rotate(part.positions.slice(i, i + 3) as unknown as Point, ...rotation);
      const n = rotate(part.normals.slice(i, i + 3) as unknown as Point, ...rotation);
      for (let axis = 0; axis < 3; axis++) { part.positions[i + axis] = p[axis]; part.normals[i + axis] = n[axis]; min[axis] = Math.min(min[axis], p[axis]); max[axis] = Math.max(max[axis], p[axis]); }
    }
    const size = Math.max(...max.map((v, i) => v - min[i])), center = max.map((v, i) => (v + min[i]) / 2);
    for (const part of parts) {
      for (let i = 0; i < part.positions.length; i++) part.positions[i] = (part.positions[i] - center[i % 3]) / size;
      Object.freeze(part.positions); Object.freeze(part.normals); Object.freeze(part.indices); Object.freeze(part);
    }
    return Object.freeze({ type, parts: Object.freeze(parts), bounds: Object.freeze({ min: Object.freeze(min.map((v, i) => (v - center[i]) / size)) as unknown as Point, max: Object.freeze(max.map((v, i) => (v - center[i]) / size)) as unknown as Point }), triangleCount: parts.reduce((sum, part) => sum + part.indices.length / 3, 0) });
  }
}

function buildGeometry(type: ItemDisplay): ItemGeometry {
  const b = new ModelBuilder();
  if (type === 'boost') {
    // Distinct flame/nozzle/body/nose silhouette; the crest is real raised mesh.
    b.lathe([[-.69, 0], [-.50, .09], [-.37, .105], [-.33, 0]], ['#ffc94f', '#ff7038', '#ff9d34'], 8);
    b.lathe([[-.43, 0], [-.40, .105], [-.28, .105], [-.26, 0]], ['#203456', '#203456', '#203456']);
    b.lathe([[-.31, 0], [-.30, .15], [-.24, .18], [-.06, .185], [.03, .185], [.27, .155], [.38, .10], [.48, 0]], ['#ffb344', '#ffb344', '#ff9d34', '#fff4d5', '#ff9d34', '#ffb344', '#fff4d5']);
    b.extrude([[-.12, -.04], [-.31, -.25], [-.34, -.43], [-.14, -.32]], .065, -.065, '#fff4d5', '#df6840');
    b.extrude([[.12, -.04], [.31, -.25], [.34, -.43], [.14, -.32]], .065, -.065, '#fff4d5', '#df6840');
    b.extrude([[.025, .28], [-.10, .06], [.003, .06], [-.045, -.11], [.13, .13], [.025, .13]], .195, .17, '#fff4d5', '#d27932');
    return b.finish(type, [0, 0, -25]);
  }
  if (type === 'shield') {
    const outline: Point2[] = [[0, -.53], [.30, -.30], [.43, .17], [.35, .40], [0, .50], [-.35, .40], [-.43, .17], [-.30, -.30]];
    b.extrude(outline, .025, -.115, '#164e80', '#164e80');
    b.plate(outline, .025, '#b2f6ff', '#38bbdf', .21);
    // Central chevron and inset jewel make the shield legible at HUD sizes.
    b.extrude([[-.22, .22], [0, .10], [.22, .22], [.17, .06], [0, -.06], [-.17, .06]], .24, .17, '#e2ffff', '#1688b3');
    b.extrude([[0, -.36], [.07, -.17], [0, -.10], [-.07, -.17]], .225, .14, '#a8f3ff', '#1688b3');
    return b.finish(type);
  }
  if (type === 'pulse') {
    b.lathe([[-.28, 0], [-.20, .16], [-.08, .245], [.08, .245], [.20, .16], [.28, 0]], ['#982dba', '#c84bdd', '#ed70e9', '#ffb8f4', '#ffd6fb'], 10);
    b.torus(.39, .043, '#d9eeff', [47, -23, 26], 24, 5);
    b.torus(.43, .039, '#a690ff', [-38, 36, -23], 24, 5);
    b.extrude([[.025, .17], [-.11, -.025], [-.012, -.025], [-.046, -.16], [.115, .052], [.024, .052]], .26, .225, '#fff0ff', '#bc39c4');
    return b.finish(type);
  }
  const hook: Point2[] = [[-.33, .22], [-.30, .38], [-.18, .49], [.13, .49], [.29, .41], [.35, .26], [.31, .11], [.19, .005], [.085, -.07], [.085, -.20], [-.10, -.20], [-.10, .006], [.035, .10], [.135, .17], [.16, .25], [.12, .31], [.045, .34], [-.08, .34], [-.14, .29], [-.15, .22]];
  b.extrude(hook, .07, -.11, '#ffbc43', '#b66328');
  const inset = hook.map(([x, y]): Point2 => [x * .90, (y - .15) * .90 + .15]);
  b.extrude(inset, .11, .068, '#fff0a6', '#f5a638');
  const dot: Point2[] = [[-.11, -.47], [.11, -.47], [.11, -.29], [-.11, -.29]];
  b.extrude(dot, .07, -.11, '#ffbc43', '#b66328');
  b.extrude(dot.map(([x, y]): Point2 => [x * .75, (y + .38) * .75 - .38]), .11, .068, '#fff0a6', '#f5a638');
  return b.finish(type, [0, 0, -7]);
}

const geometryCache = new Map<ItemDisplay, ItemGeometry>();
/** Stable immutable descriptors, shared by GPU models and CPU portraits. */
export function getItemGeometry(type: ItemDisplay): ItemGeometry {
  if (!geometryCache.has(type)) geometryCache.set(type, buildGeometry(type));
  return geometryCache.get(type)!;
}

type ModelResource = { mesh: pc.Mesh; material: pc.StandardMaterial };
const appResources = new WeakMap<pc.AppBase, Map<ItemDisplay, ModelResource[]>>();
/** Returns an independent entity; expensive meshes/materials are reused per app.
 * A cache reference keeps meshes alive even when every current instance is removed.
 */
export function createItemModel(app: pc.AppBase, type: ItemDisplay): pc.Entity {
  let cache = appResources.get(app);
  if (!cache) {
    cache = new Map(); appResources.set(app, cache);
    const owned = cache;
    app.once('destroy', () => {
      for (const resources of owned.values()) for (const { mesh, material } of resources) { mesh.decRefCount(); mesh.destroy(); material.destroy(); }
      owned.clear(); appResources.delete(app);
    });
  }
  if (!cache.has(type)) cache.set(type, getItemGeometry(type).parts.map(part => {
    const mesh = new pc.Mesh(app.graphicsDevice);
    mesh.setPositions([...part.positions]); mesh.setNormals([...part.normals]); mesh.setIndices([...part.indices]); mesh.update(pc.PRIMITIVE_TRIANGLES); mesh.incRefCount();
    const material = new pc.StandardMaterial();
    material.name = `${type} ${part.color}`; material.diffuse = new pc.Color().fromString(part.color);
    material.emissive = new pc.Color().fromString(part.color).mulScalar(.065);
    material.useMetalness = true; material.metalness = part.metalness; material.gloss = .48;
    material.cull = pc.CULLFACE_BACK; material.blendType = pc.BLEND_NONE; material.depthWrite = true; material.update();
    return { mesh, material };
  }));
  const entity = new pc.Entity(ITEM_MODEL_METADATA.items[type].name, app);
  entity.addComponent('render', { meshInstances: cache.get(type)!.map(({ mesh, material }) => new pc.MeshInstance(mesh, material)), castShadows: true, receiveShadows: true });
  return entity;
}

const imageCache = new Map<ItemDisplay, string>();
/** Render the actual model into a deterministic transparent SVG portrait.
 * No WebGL, DOM, canvas, font, downloaded image or separate icon asset is needed.
 * Backface culling, per-face normal lighting and far-to-near triangle ordering
 * provide an orthographic 3D render that also works during loading and in tests.
 */
export function itemImage(type: ItemDisplay): string {
  if (imageCache.has(type)) return imageCache.get(type)!;
  const geometry = getItemGeometry(type), light = unit([-.45, .85, 1.6]);
  const faces: { points: Point[]; z: number; fill: string }[] = [];
  const transformed = geometry.parts.map(part => ({ part, vertices: Array.from({ length: part.positions.length / 3 }, (_, i) => rotate(part.positions.slice(i * 3, i * 3 + 3) as unknown as Point, 16, -22)) }));
  const all = transformed.flatMap(({ vertices }) => vertices);
  const minX = Math.min(...all.map(p => p[0])), maxX = Math.max(...all.map(p => p[0]));
  const minY = Math.min(...all.map(p => p[1])), maxY = Math.max(...all.map(p => p[1]));
  const scale = 218 / Math.max(maxX - minX, maxY - minY), cx = (minX + maxX) / 2, cy = (minY + maxY) / 2;
  for (const { part, vertices } of transformed) for (let i = 0; i < part.indices.length; i += 3) {
    const points = part.indices.slice(i, i + 3).map(index => vertices[index]);
    const normal = unit(cross(sub(points[1], points[0]), sub(points[2], points[0])));
    if (normal[2] <= 1e-7) continue;
    const brightness = .55 + .45 * Math.max(0, dot(normal, light));
    const rgb = [1, 3, 5].map(offset => Math.round(parseInt(part.color.slice(offset, offset + 2), 16) * brightness));
    faces.push({ points, z: points.reduce((sum, p) => sum + p[2], 0) / 3, fill: `rgb(${rgb.join(',')})` });
  }
  faces.sort((a, b) => a.z - b.z);
  const triangles = faces.map(({ points, fill }) => `<path d="M${points.map(p => `${((p[0] - cx) * scale + 128).toFixed(2)},${(128 - (p[1] - cy) * scale).toFixed(2)}`).join('L')}Z" fill="${fill}" stroke="${fill}" stroke-width="0.55" stroke-linejoin="round"/>`).join('');
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" width="256" height="256" role="img"><title>${ITEM_MODEL_METADATA.items[type].name}</title><g>${triangles}</g></svg>`;
  const image = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
  imageCache.set(type, image); return image;
}

src/item-pickups.ts.content:
import type { ItemKind, ItemDisplay } from './item-models';

export const ITEM_KINDS: readonly ItemKind[] = ['boost', 'shield', 'pulse'];
export const MYSTERY_CHANCE = .25;
export const PICKUP_RESPAWN_SECONDS = 8;
export interface PickupState {
  display: ItemDisplay;
  cool: number;
  mesh: { enabled: boolean };
  models: Record<ItemDisplay, { enabled: boolean }>;
}
const roll = (rng: () => number) => Math.min(1 - Number.EPSILON, Math.max(0, rng()));
export const randomItem = (rng = Math.random): ItemKind => ITEM_KINDS[Math.floor(roll(rng) * ITEM_KINDS.length)];
export function rollDisplay(rng = Math.random): ItemDisplay {
  return roll(rng) < MYSTERY_CHANCE ? 'mystery' : randomItem(rng);
}
export function setPickupDisplay(box: PickupState, display: ItemDisplay) {
  box.display = display;
  for (const [kind, model] of Object.entries(box.models)) model.enabled = kind === display;
}
export function resetPickup(box: PickupState, rng = Math.random) {
  box.cool = 0;
  setPickupDisplay(box, rollDisplay(rng));
  box.mesh.enabled = true;
}
/** Claim synchronously before returning the reward: a second racer cannot claim it. */
export function claimPickup(box: PickupState, occupied: boolean, rng = Math.random): ItemKind | null {
  if (occupied || box.cool > 0 || !box.mesh.enabled) return null;
  const reward = box.display === 'mystery' ? randomItem(rng) : box.display;
  box.cool = PICKUP_RESPAWN_SECONDS;
  box.mesh.enabled = false; // Parent hides the glass, frame AND enclosed model immediately.
  return reward;
}
/** Call only while racing. Pausing/countdown/menu must not consume the cooldown. */
export function advancePickup(box: PickupState, dt: number, rng = Math.random) {
  if (box.cool <= 0) return;
  box.cool = Math.max(0, box.cool - Math.max(0, dt));
  if (box.cool === 0) resetPickup(box, rng);
}

