/** World pickups only: keep their enclosed model, frame and collection bounds
 * at the same scale without affecting HUD icons or launched items. */
export const PICKUP_SCALE = 1.2;
export const PICKUP_LONGITUDINAL_HALF_RANGE = 1.8 * PICKUP_SCALE;
export const PICKUP_LATERAL_HALF_RANGE = 1.25 * PICKUP_SCALE;

